def ac0_parity_circuit_size(f):
    n = int(math.log2(len(f)))
    if 2**n != len(f):
        raise ValueError("Invalid function length")
    circuit_size = 0
    for i in range(n):
        circuit_size += (1 << i)
    return circuit_size

def minimal_rank(L):
    # Implement Gaussian elimination to find the rank of L
    n = len(L)
    rank = 0
    for i in range(n):
        if all(row[i] == 0 for row in L[i:]):
            continue
        rank += 1
        for j in range(i + 1, n):
            if L[j][i] != 0:
                L[j], L[i] = L[i], L[j]
                break
        for j in range(n):
            if j == i:
                continue
            factor = L[j][i] / L[i][i]
            for k in range(n):
                L[j][k] -= factor * L[i][k]
    return rank

